package org.sleepwell.app;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import java.util.*;
/** Separate private job journal. No mutation of sleep records or portable backups. Worker-only. */
final class AutoCloudBackupStore extends SQLiteOpenHelper {
 static final String DATABASE="automatic_metadata_backup_v1.db";
 AutoCloudBackupStore(Context c){this(c,DATABASE);}AutoCloudBackupStore(Context c,String name){super(c,name,null,1);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE owner(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL,token TEXT NOT NULL,tree TEXT NOT NULL,revision INTEGER NOT NULL,message TEXT NOT NULL)");db.execSQL("INSERT INTO owner VALUES(1,0,'','',0,'Off')");db.execSQL("CREATE TABLE tasks(identity TEXT PRIMARY KEY,session INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,tree TEXT NOT NULL,revision INTEGER NOT NULL,token TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL,due INTEGER NOT NULL,uri TEXT NOT NULL DEFAULT '',name TEXT NOT NULL DEFAULT '',sha TEXT NOT NULL DEFAULT '',size INTEGER NOT NULL DEFAULT 0,issue TEXT NOT NULL DEFAULT '')");db.execSQL("CREATE INDEX backup_due ON tasks(state,due)");}
 public void onUpgrade(SQLiteDatabase db,int old,int next){throw new IllegalStateException("Unsupported backup journal");}
 static final class Owner {final boolean enabled;final String token,tree,message;final long revision;Owner(boolean on,String token,String tree,long revision,String message){enabled=on;this.token=token;this.tree=tree;this.revision=revision;this.message=message;}}
 static final class Task {final String identity,tree,token,state,uri,name,sha,issue;final long session,start,end,revision,due,size;final int attempts;Task(Cursor c){identity=c.getString(0);session=c.getLong(1);start=c.getLong(2);end=c.getLong(3);tree=c.getString(4);revision=c.getLong(5);token=c.getString(6);state=c.getString(7);attempts=c.getInt(8);due=c.getLong(9);uri=c.getString(10);name=c.getString(11);sha=c.getString(12);size=c.getLong(13);issue=c.getString(14);}}
 Owner owner(){try(Cursor c=getReadableDatabase().rawQuery("SELECT enabled,token,tree,revision,message FROM owner WHERE id=1",null)){if(!c.moveToFirst())throw new IllegalStateException("Backup owner missing");return new Owner(c.getInt(0)!=0,c.getString(1),c.getString(2),c.getLong(3),c.getString(4));}}
 boolean current(String token){Owner o=owner();return o.enabled&&o.token.equals(token);}
 void message(String value){ContentValues v=new ContentValues();v.put("message",value);if(getWritableDatabase().update("owner",v,"id=1",null)!=1)throw new IllegalStateException("Backup owner changed");}
 void configure(boolean on,CloudBackupSettings.Destination d){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.execSQL("UPDATE tasks SET state=CASE WHEN state IN ('CREATING','CREATED') THEN 'UNCERTAIN' ELSE 'CANCELLED' END,issue='Automatic backup settings changed; provider files are kept' WHERE state IN ('PENDING','PREPARING','CREATING','CREATED')");ContentValues v=new ContentValues();v.put("enabled",on?1:0);v.put("token",UUID.randomUUID().toString());v.put("tree",on?d.tree:"");v.put("revision",on?d.revision:0);v.put("message",on?"On · waits for the next successfully saved tracked night":"Off · existing provider files are kept");db.update("owner",v,"id=1",null);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 boolean enqueue(long id,long start,long end,long now){Owner o=owner();if(!o.enabled)return false;String identity=AutoCloudBackupPolicy.key(id,start,end,o.revision,o.tree);if(task(identity)!=null)return false;if(count("PENDING","PREPARING","CREATING","CREATED")>=AutoCloudBackupPolicy.MAX_PENDING){message("Automatic backup queue is full. Save a manual version; queued nights are kept.");return false;}ContentValues v=new ContentValues();v.put("identity",identity);v.put("session",id);v.put("start",start);v.put("end",end);v.put("tree",o.tree);v.put("revision",o.revision);v.put("token",o.token);v.put("state","PENDING");v.put("attempts",0);v.put("due",now);if(getWritableDatabase().insertOrThrow("tasks",null,v)<0)throw new IllegalStateException("Backup request not saved");message("Queued after a saved night · Android may defer delivery");return true;}
 Task task(String id){try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM tasks WHERE identity=?",new String[]{id})){return c.moveToFirst()?new Task(c):null;}}
 Task next(){try(Cursor c=getReadableDatabase().rawQuery("SELECT * FROM tasks WHERE state='PENDING' ORDER BY due, rowid LIMIT 1",null)){return c.moveToFirst()?new Task(c):null;}}
 int count(String... states){StringJoiner placeholders=new StringJoiner(",");for(String ignored:states)placeholders.add("?");try(Cursor c=getReadableDatabase().rawQuery("SELECT count(*) FROM tasks WHERE state IN ("+placeholders+")",states)){c.moveToFirst();return c.getInt(0);}}
 int countOwned(String... states){StringJoiner placeholders=new StringJoiner(",");for(String ignored:states)placeholders.add("?");String[] args=new String[states.length+1];args[0]=owner().token;System.arraycopy(states,0,args,1,states.length);try(Cursor c=getReadableDatabase().rawQuery("SELECT count(*) FROM tasks WHERE token=? AND state IN ("+placeholders+")",args)){c.moveToFirst();return c.getInt(0);}}
 void claim(Task t){ContentValues v=new ContentValues();v.put("state","PREPARING");v.put("attempts",t.attempts+1);if(getWritableDatabase().update("tasks",v,"identity=? AND state='PENDING' AND token=?",new String[]{t.identity,t.token})!=1)throw new IllegalStateException("Backup request changed");message("Preparing the latest metadata snapshot…");}
 void stage(Task t,String stage,CloudBackupCopy.Document d){Task saved=task(t.identity);if(saved==null||!saved.token.equals(t.token))throw new IllegalStateException("Backup request changed");ContentValues v=new ContentValues();boolean retired=saved.state.equals("UNCERTAIN");if(!retired)v.put("state",stage);if(d!=null){v.put("uri",d.uri);v.put("name",d.name);}if(getWritableDatabase().update("tasks",v,"identity=? AND token=? AND state IN ('PREPARING','CREATING','UNCERTAIN')",new String[]{t.identity,t.token})!=1)throw new IllegalStateException("Backup was cancelled");if(current(t.token))message("Creating and verifying automatic backup…");}
 void complete(Task t,CloudBackupCopy.Receipt r){ContentValues v=new ContentValues();v.put("state","VERIFIED");v.put("uri",r.document.uri);v.put("name",r.document.name);v.put("sha",r.sha);v.put("size",r.size);v.put("issue","");if(getWritableDatabase().update("tasks",v,"identity=? AND token=? AND state IN ('CREATED','UNCERTAIN')",new String[]{t.identity,t.token})!=1)throw new IllegalStateException("Automatic receipt could not be saved");if(current(t.token))message("Automatic metadata version read-back verified · provider manages remote upload");}
 void failure(Task t,long now,String issue){Task saved=task(t.identity);if(saved==null||saved.state.equals("VERIFIED")||saved.state.equals("CANCELLED"))return;boolean created=saved.state.equals("CREATING")||saved.state.equals("CREATED")||saved.state.equals("UNCERTAIN")||!saved.uri.isEmpty();String state=!created&&issue.equals("oversize")?"FAILED":AutoCloudBackupPolicy.failure(created,saved.attempts);ContentValues v=new ContentValues();v.put("state",state);v.put("due",AutoCloudBackupPolicy.retryAt(now,saved.attempts));v.put("issue",issue);getWritableDatabase().update("tasks",v,"identity=?",new String[]{t.identity});if(current(t.token))message(!created&&issue.equals("oversize")?"Metadata snapshot exceeds the existing 8 MiB limit. Nothing was uploaded or removed. Automatic retry stopped.":created?"Automatic backup needs review: a partial or complete provider file may remain. No automatic replay.":state.equals("PENDING")?"Backup preparation failed · retry queued ("+saved.attempts+"/3)":"Automatic backup failed after 3 preparation attempts. Retry explicitly.");}
 void recover(){getWritableDatabase().execSQL("UPDATE tasks SET state='UNCERTAIN',issue='Interrupted after provider creation may have begun' WHERE state IN ('CREATING','CREATED')");getWritableDatabase().execSQL("UPDATE tasks SET state=CASE WHEN attempts<3 THEN 'PENDING' ELSE 'FAILED' END,issue='Preparation interrupted' WHERE state='PREPARING'");if(countOwned("UNCERTAIN")>0)message("A previous automatic write was interrupted. Review the folder before retrying; a partial version may remain.");}
 void retry(long now){Owner o=owner();if(!o.enabled)return;ContentValues v=new ContentValues();v.put("state","PENDING");v.put("attempts",0);v.put("due",now);v.put("issue","");getWritableDatabase().update("tasks",v,"token=? AND state IN ('UNCERTAIN','FAILED')",new String[]{o.token});message("Retry requested · a new version will be created");}
 void reject(Task t,String reason){ContentValues v=new ContentValues();v.put("state","CANCELLED");v.put("issue",reason);getWritableDatabase().update("tasks",v,"identity=?",new String[]{t.identity});message(reason);}
}
